147	interface MatrixDimensionOption extends MatrixCellStyleOption, MatrixDimensionLevelOption {
148	    type?: 'category'; // For internal usage; force be 'category'.
149	    show?: boolean;
150	    data?: MatrixDimensionCellLooseOption[];
151	    // `levels[0]`: the topmost (for x dimension) or leftmost (for y dimension) level.
152	    // If not specified, use null/undefined, such as `levels: [null, null, {levelSize: 10}]`
153	    levels?: (MatrixDimensionLevelOption | NullUndefined)[];
154	    dividerLineStyle?: LineStyleOption;
155	}
156	
157	export interface MatrixDimensionCellOption extends MatrixBaseCellOption {
158	    // Use it to define a coord in matrix.
159	    // Do not use type `OrdinalRawValue` here. Number input is forbiden due to the possible confusion.
160	    // e.g., if `matrix.x.data: [1, 2, 3]` is allowed, then querying `coord: [1, null]` will actually get
161	    // the second column, since number represents the index (i.e. `MatrixXYLocator` or `OrdinalNumber`).
162	    value?: string;
163	    // column width (for x dimension) or row height (for y dimension).
164	    // If not specified (null/undefined), auto calculate it.
165	    // Only available on leaves, to avoid unnecessary complex.
166	    // If it is a percentage, such as '30%', based on the matrix width/height, rather than the canvas size.
167	    size?: PositionSizeOption;
168	    children?: MatrixDimensionCellOption[];
169	}
170	export type MatrixDimensionCellLooseOption = MatrixDimensionCellOption | MatrixDimensionCellOption['value'];
171	
172	export interface MatrixDimensionLevelOption {
173	    // `matrix.levelSize` specifies the default size of every tree levels.
174	    // `matrix.levels[i].levelSize` specifies the size of a certain level.
175	    // For x dimension, that is height; for y dimension, that is width.
176	    // If not specified (null/undefined), auto calculate it.
177	    // If it is a percentage, such as '30%', based on the matrix width/height, rather than the canvas size.
178	    levelSize?: PositionSizeOption;
179	    // Other level specific options may added if needed, such as border-bottom/right style.
180	}
181	
182	export interface MatrixDimensionModel extends Model<MatrixDimensionOption> {
183	}
184	
185	/**
186	 * Two levels of cascade inheritance:
187	 *  - priority-high: style options defined in `matrix.x/y/coner/body.data[i]` (in cell)
188	 *  - priority-low: style options defined in `matrix.x/y/coner/body`
189	 */
190	export interface MatrixCellStyleOption {
191	    // [NOTE - padding]:
192	    //  - Consider the option for the space between cell boundary to text, percentage value for
193	    //    `label.width/height` is not supported, because it is not ideal - the padding would vary
194	    //    with the cell size, making the layout inconsistent.
195	    //  - The inner text padding uses `lable.style.padding`.
196	    //    The text truncation rect is obtained by cell rect minus by padding.
197	    //  - The inner series / other coord sys padding is not supported, to avoid necessary complexity.
198	    //    Consider some series, such as heatmap, prefer no padding.
199	    label?: LabelOption;
200	    itemStyle?: ItemStyleOption;
201	    cursor?: string;
202	    // By default, auto decide whether to be silent, considering tooltip.
203	    silent?: boolean | NullUndefined;
204	    // Used when style conflict - especially for thick border style.
205	    z2?: number;
206	}
207	
208	export interface MatrixTooltipFormatterParams {
209	    componentType: 'matrix'
210	    matrixIndex: number
211	    name: string
212	    $vars: ['name', 'xyLocator']
213	}
