272	class MatrixModel extends ComponentModel<MatrixOption> implements CoordinateSystemHostModel {
273	    static type = 'matrix';
274	    type = MatrixModel.type;
275	
276	    coordinateSystem: Matrix;
277	
278	    static layoutMode = 'box' as const;
279	
280	    private _dimModels: {
281	        x: MatrixDimensionModel;
282	        y: MatrixDimensionModel;
283	    };
284	
285	    private _body: MatrixBodyCorner<'body'>;
286	    private _corner: MatrixBodyCorner<'corner'>;
287	
288	    static defaultOption: MatrixOption = defaultMatrixOption;
289	
290	    optionUpdated(): void {
291	        // Simply re-create all to follow model changes.
292	
293	        const dimModels = this._dimModels = {
294	            // Do not use matrixModel as the parent model, for preventing from cascade-fetching options to it.
295	            x: new MatrixDimensionModel(this.get('x', true) || {}),
296	            y: new MatrixDimensionModel(this.get('y', true) || {}),
297	        };
298	
299	        dimModels.x.option.type = dimModels.y.option.type = 'category';
300	        const xDim = dimModels.x.dim = new MatrixDim('x', dimModels.x);
301	        const yDim = dimModels.y.dim = new MatrixDim('y', dimModels.y);
302	
303	        const dims = {x: xDim, y: yDim};
304	        this._body = new MatrixBodyCorner(
305	            'body', new Model(this.getShallow('body')), dims
306	        );
307	        this._corner = new MatrixBodyCorner(
308	            'corner', new Model(this.getShallow('corner')), dims
309	        );
310	    }
311	
312	    getDimensionModel(dim: 'x' | 'y'): MatrixDimensionModel {
313	        return this._dimModels[dim];
314	    }
315	
316	    getBody(): MatrixBodyCorner<'body'> {
317	        return this._body;
318	    }
319	
320	    getCorner(): MatrixBodyCorner<'corner'> {
321	        return this._corner;
322	    }
323	
324	}
