369	        const y2Original = shape.y + shape.height;
370	        shape.x = subPixelOptimize(shape.x, lineWidth, true);
371	        shape.y = subPixelOptimize(shape.y, lineWidth, true);
372	        shape.width = subPixelOptimize(x2Original, lineWidth, true) - shape.x;
373	        shape.height = subPixelOptimize(y2Original, lineWidth, true) - shape.y;
374	    }
375	    return new Rect({
376	        shape,
377	        style: style,
378	        z2,
379	    });
380	}
